<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'

type User = { id: number; username: string; name: string; role: 'ADMIN' | 'USER'; token: string }
type ManagedUser = { id: number; username: string; name: string; role: 'ADMIN' | 'USER'; status: string; work_unit?: string; job_title?: string; phone?: string; email?: string; created_at: string }
type Category = { id: number; name: string; description?: string }
type Field = { id: number; field_name: string; field_key: string; field_type: string; required: boolean; options?: string[] | string | null; sort_order: number }
type AttributeValue = string | number | boolean | undefined
type Equipment = { id: number; equipment_code: string; name: string; category_id: number; category_name: string; unit_id: number; unit_name?: string; status: string; location?: string; department?: string; task_name?: string; image_attachment_id?: number; attributes?: Record<string, AttributeValue>; created_by?: number }
type Unit = { id: number; name: string; parent_id?: number | null; level: number }
type EquipmentEvent = { id: number; event_type: string; old_status?: string; new_status?: string; description?: string; occurred_at: string; operator_name?: string }
type Task = { id: number; task_code: string; name: string; type?: string; location?: string; start_time?: string; end_time?: string; status: string; leader?: string; description?: string; created_by: number; creator_name?: string; equipment_total: number; equipment_outstanding: number }
type TaskEquipment = { id: number; equipment_id: number; equipment_code: string; equipment_name: string; category_name: string; assigned_user?: string; returned_at?: string; return_status?: string; current_status: string }
type HistoryEvent = { id: number; event_type: string; old_status?: string; new_status?: string; description?: string; occurred_at: string; equipment_code: string; equipment_name: string; task_code?: string; operator_name?: string }
type Attachment = { id: number; file_name: string; file_type?: string; file_size?: number; created_at: string }
type Profile = { username: string; name: string; role: 'ADMIN' | 'USER'; work_unit?: string; job_title?: string; phone?: string; email?: string; address?: string; remarks?: string }

const api = import.meta.env.VITE_API_BASE_URL
const document = globalThis.document
const user = ref<User | null>(JSON.parse(localStorage.getItem('equipment_user') || 'null'))
const authMode = ref<'login' | 'register'>('login')
const authForm = ref({ username: '', password: '', name: '' })
const message = ref('')
const error = ref('')
const categories = ref<Category[]>([])
const equipment = ref<Equipment[]>([])
const selectedCategoryId = ref<number | null>(null)
const fields = ref<Field[]>([])
const categoryForm = ref({ name: '', description: '' })
const fieldForm = ref({ fieldName: '', fieldKey: '', fieldType: 'TEXT', required: false, optionsText: '', sortOrder: 0 })
const equipmentForm = ref({ id: 0, categoryId: 0, unitId: 0, name: '', location: '', department: '', attributes: {} as Record<string, AttributeValue> })
const selected = ref<Equipment | null>(null)
const events = ref<EquipmentEvent[]>([])
const view = ref<'dashboard' | 'list' | 'form' | 'detail' | 'fields' | 'tasks' | 'task-form' | 'task-detail' | 'history' | 'profile' | 'users'>('dashboard')
watch(user, (currentUser) => {
  if (currentUser) view.value = 'dashboard'
})
const statusForm = ref({ status: 'IN_STOCK', description: '' })
const tasks = ref<Task[]>([])
const selectedTask = ref<{ task: Task; equipment: TaskEquipment[] } | null>(null)
const taskForm = ref({ name: '', type: '', location: '', startTime: '', endTime: '', leader: '', participants: '', description: '', equipmentIds: [] as number[] })
const returnForm = ref({ returnStatus: 'IN_STOCK', mileage: '', usageDescription: '', damageDescription: '', transferDescription: '', description: '' })
const eventForm = ref({ eventType: 'TRANSFER', handlerName: '', description: '' })
const eventEquipment = ref<TaskEquipment | null>(null)
const history = ref<HistoryEvent[]>([])
const historyFilter = ref({ equipmentId: '', taskId: '', eventType: '', from: '', to: '' })
const dashboard = ref<{ equipment: Record<string, number>; tasks: Record<string, number>; recentTasks: Task[]; recentEvents: HistoryEvent[] } | null>(null)
const attachments = ref<Attachment[]>([])
const listFilter = ref({ keyword: '', categoryId: '', status: '' })
const units = ref<Unit[]>([])
const selectedUnitId = ref<number | null>(null)
const unitForm = ref({ name: '', parentId: '' })
const unitRenameId = ref<number | null>(null)
const unitRenameName = ref('')
const detailUnitId = ref(0)
const fieldLabels = ref<Record<string, string>>({})
const expandedUnits = ref<number[]>([])
const profileForm = ref<Profile>({ username: '', name: '', role: 'USER', work_unit: '', job_title: '', phone: '', email: '', address: '', remarks: '' })
const managedUsers = ref<ManagedUser[]>([])
const statusNames: Record<string, string> = { IN_STOCK: '在库', IN_TASK: '执行任务中', MAINTENANCE: '维护保养中', DISABLED: '停用' }
const fieldTypeNames: Record<string, string> = { TEXT: '文本', TEXTAREA: '长文本', INTEGER: '整数', DECIMAL: '小数', DATE: '日期', DATETIME: '日期时间', BOOLEAN: '是/否', SELECT: '下拉选项' }
const headers = computed(() => user.value ? { Authorization: `Bearer ${user.value.token}` } : {})
const isAdmin = computed(() => user.value?.role === 'ADMIN')
const canEdit = computed(() => !!selected.value && (isAdmin.value || selected.value.created_by === user.value?.id))

async function request(path: string, options: RequestInit = {}) {
  const response = await fetch(`${api}${path}`, { ...options, headers: { 'Content-Type': 'application/json', ...headers.value, ...(options.headers || {}) } as Record<string, string> })
  const data = await response.json().catch(() => ({}))
  if (!response.ok) throw new Error(data.message || '请求失败')
  return data
}
function notify(text: string, failed = false) { failed ? error.value = text : message.value = text; window.setTimeout(() => { message.value = ''; error.value = '' }, 3500) }
function parseOptions(value: Field) { if (Array.isArray(value.options)) return value.options; if (typeof value.options === 'string') { try { const parsed = JSON.parse(value.options); return Array.isArray(parsed) ? parsed : [] } catch { return [] } } return [] }
function parseAttributes(value: unknown): Record<string, AttributeValue> { if (value && typeof value === 'object') return value as Record<string, AttributeValue>; if (typeof value === 'string') { try { return JSON.parse(value) as Record<string, AttributeValue> } catch { return {} } } return {} }
function normalizeFieldKey() { fieldForm.value.fieldKey = fieldForm.value.fieldKey || fieldForm.value.fieldName.trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '') }

async function submitAuth() {
  try { const data = await request(authMode.value === 'login' ? '/auth/login' : '/auth/register', { method: 'POST', body: JSON.stringify(authForm.value) }); user.value = data; localStorage.setItem('equipment_user', JSON.stringify(data)); await loadAll(); notify('登录成功') }
  catch (e) { notify((e as Error).message, true) }
}
function logout() { user.value = null; localStorage.removeItem('equipment_user'); view.value = 'list' }
async function openProfile() {
  try {
    profileForm.value = await request('/users/me') as Profile
    view.value = 'profile'
  } catch (e) { notify((e as Error).message, true) }
}
async function saveProfile() {
  try {
    const data = await request('/users/me', { method: 'PUT', body: JSON.stringify(profileForm.value) }) as User
    user.value = data
    localStorage.setItem('equipment_user', JSON.stringify(data))
    await openProfile()
    notify('个人信息已保存')
  } catch (e) { notify((e as Error).message, true) }
}
async function openUsers() {
  try { managedUsers.value = await request('/users') as ManagedUser[]; view.value = 'users' }
  catch (e) { notify((e as Error).message, true) }
}
async function updateUserRole(item: ManagedUser, role: 'ADMIN' | 'USER') {
  if (item.role === role) return
  try { await request(`/users/${item.id}/role`, { method: 'PUT', body: JSON.stringify({ role }) }); item.role = role; notify('用户类型已更新') }
  catch (e) { notify((e as Error).message, true); await openUsers() }
}
async function loadAll() { if (!user.value) return; categories.value = await request('/categories'); units.value = await request('/units'); const allFields = await Promise.all(categories.value.map(category => request(`/categories/${category.id}/fields`) as Promise<Field[]>)); fieldLabels.value = Object.fromEntries(allFields.flat().map(field => [field.field_key, field.field_name])); await loadEquipment(); tasks.value = await request('/tasks'); dashboard.value = await request('/dashboard'); if (!equipmentForm.value.categoryId && categories.value.length) equipmentForm.value.categoryId = categories.value[0].id; if (!equipmentForm.value.unitId && units.value.length) equipmentForm.value.unitId = units.value[0].id }
async function loadEquipment() { const query = new URLSearchParams(); if (listFilter.value.keyword) query.set('keyword', listFilter.value.keyword); if (listFilter.value.categoryId) query.set('categoryId', listFilter.value.categoryId); if (listFilter.value.status) query.set('status', listFilter.value.status); if (selectedUnitId.value) query.set('unitId', String(selectedUnitId.value)); equipment.value = (await request(`/equipment?${query}`)).map((item: Equipment) => ({ ...item, attributes: parseAttributes(item.attributes) })) }
function rawUnitChildren(parentId: number | null) { return units.value.filter(unit => (unit.parent_id ?? null) === parentId) }
function unitChildren(parentId: number | null) { return parentId === null || expandedUnits.value.includes(parentId) ? rawUnitChildren(parentId) : [] }
function hasChildren(unit: Unit) { return rawUnitChildren(unit.id).length > 0 }
function isExpanded(unit: Unit) { return expandedUnits.value.includes(unit.id) }
function toggleUnit(unit: Unit) { expandedUnits.value = isExpanded(unit) ? expandedUnits.value.filter(id => id !== unit.id) : [...expandedUnits.value, unit.id] }
function selectUnit(id: number | null) { selectedUnitId.value = id; const unit = id ? units.value.find(item => item.id === id) : null; if (unit && hasChildren(unit)) toggleUnit(unit); loadEquipment() }
async function createUnit() { try { if (!unitForm.value.name.trim()) throw new Error('请输入单位名称'); await request('/units', { method: 'POST', body: JSON.stringify({ name: unitForm.value.name, parentId: unitForm.value.parentId ? Number(unitForm.value.parentId) : null }) }); unitForm.value = { name: '', parentId: '' }; units.value = await request('/units'); notify('单位已创建') } catch (e) { notify((e as Error).message, true) } }
function startRenameUnit(item: Unit) { unitRenameId.value = item.id; unitRenameName.value = item.name; (document.getElementById('unit-rename-dialog') as HTMLDialogElement | null)?.showModal() }
async function renameUnit() { try { if (!unitRenameId.value || !unitRenameName.value.trim()) throw new Error('请输入单位名称'); await request(`/units/${unitRenameId.value}`, { method: 'PUT', body: JSON.stringify({ name: unitRenameName.value }) }); units.value = await request('/units'); unitRenameId.value = null; notify('单位名称已修改'); await loadEquipment() } catch (e) { notify((e as Error).message, true) } }
async function saveUnitRename() { await renameUnit(); if (!unitRenameId.value) (document.getElementById('unit-rename-dialog') as HTMLDialogElement | null)?.close() }
async function deleteUnit(unit: Unit) { if (!confirm(`删除“${unit.name}”及全部下级单位？其中装备会转入“未分配单位”，装备数据不会删除。`)) return; try { await request(`/units/${unit.id}`, { method: 'DELETE' }); if (selectedUnitId.value === unit.id) selectedUnitId.value = null; units.value = await request('/units'); expandedUnits.value = expandedUnits.value.filter(id => units.value.some(unit => unit.id === id)); await loadEquipment(); notify('单位及下级单位已删除，关联装备已转入未分配单位') } catch (e) { notify((e as Error).message, true) } }
function equipmentImage(item: Equipment) { return item.image_attachment_id ? `${api}/attachments/${item.image_attachment_id}/download` : '' }
function briefAttributes(item: Equipment) { return Object.entries(parseAttributes(item.attributes)).slice(0, 3).map(([key, value]) => `${fieldLabels.value[key] || key}: ${value === true ? '是' : value === false ? '否' : value}`).join(' · ') }
async function loadFields(categoryId: number) { fields.value = categoryId ? await request(`/categories/${categoryId}/fields`) : [] }
watch(() => equipmentForm.value.categoryId, async (id, old) => { if (id && id !== old) { await loadFields(id); if (!equipmentForm.value.id) equipmentForm.value.attributes = {} } })

async function createCategory() { try { const data = await request('/categories', { method: 'POST', body: JSON.stringify(categoryForm.value) }); categoryForm.value = { name: '', description: '' }; await loadAll(); selectedCategoryId.value = data.id; await openFields(data.id); notify('类别已创建') } catch (e) { notify((e as Error).message, true) } }
async function openFields(id: number) { selectedCategoryId.value = id; await loadFields(id); view.value = 'fields' }
async function addField() {
  try {
    normalizeFieldKey(); if (!selectedCategoryId.value || !fieldForm.value.fieldKey) throw new Error('请填写字段名称和字段键名')
    const options = fieldForm.value.fieldType === 'SELECT' ? JSON.stringify(fieldForm.value.optionsText.split(/[,，\n]/).map(x => x.trim()).filter(Boolean)) : null
    await request(`/categories/${selectedCategoryId.value}/fields`, { method: 'POST', body: JSON.stringify({ fieldName: fieldForm.value.fieldName, fieldKey: fieldForm.value.fieldKey, fieldType: fieldForm.value.fieldType, required: fieldForm.value.required, options, sortOrder: fieldForm.value.sortOrder }) })
    fieldForm.value = { fieldName: '', fieldKey: '', fieldType: 'TEXT', required: false, optionsText: '', sortOrder: fields.value.length + 1 }; await loadFields(selectedCategoryId.value); notify('字段已添加')
  } catch (e) { notify((e as Error).message, true) }
}
async function removeField(field: Field) { if (!confirm(`删除字段“${field.field_name}”？已有装备中的历史值不会删除。`)) return; try { await request(`/categories/${selectedCategoryId.value}/fields/${field.id}`, { method: 'DELETE' }); await loadFields(selectedCategoryId.value!); notify('字段已删除') } catch (e) { notify((e as Error).message, true) } }

function blankEquipment() { equipmentForm.value = { id: 0, categoryId: categories.value[0]?.id || 0, unitId: selectedUnitId.value || units.value[0]?.id || 0, name: '', location: '', department: '', attributes: {} }; selected.value = null; view.value = 'form' }
async function editEquipment(item: Equipment) { const detail = await request(`/equipment/${item.id}`); detail.attributes = parseAttributes(detail.attributes); selected.value = detail; equipmentForm.value = { id: detail.id, categoryId: detail.category_id, unitId: detail.unit_id, name: detail.name, location: detail.location || '', department: detail.department || '', attributes: detail.attributes || {} }; await loadFields(detail.category_id); view.value = 'form' }
function validateDynamicFields() { for (const field of fields.value) { const value = equipmentForm.value.attributes[field.field_key]; if (field.required && (value === undefined || value === null || value === '')) throw new Error(`请填写：${field.field_name}`); if (value !== undefined && value !== '' && field.field_type === 'INTEGER' && !Number.isInteger(Number(value))) throw new Error(`${field.field_name}必须为整数`); if (value !== undefined && value !== '' && field.field_type === 'DECIMAL' && Number.isNaN(Number(value))) throw new Error(`${field.field_name}必须为数字`) } }
async function saveEquipment() { try { validateDynamicFields(); if (!equipmentForm.value.unitId) throw new Error('请选择所属单位'); const payload = { categoryId: equipmentForm.value.categoryId, unitId: equipmentForm.value.unitId, name: equipmentForm.value.name, location: equipmentForm.value.location, department: equipmentForm.value.department, attributes: JSON.stringify(equipmentForm.value.attributes) }; const path = equipmentForm.value.id ? `/equipment/${equipmentForm.value.id}` : '/equipment'; await request(path, { method: equipmentForm.value.id ? 'PUT' : 'POST', body: JSON.stringify(payload) }); await loadAll(); notify(equipmentForm.value.id ? '装备已更新' : '装备已创建'); view.value = 'list' } catch (e) { notify((e as Error).message, true) } }
async function openDetail(item: Equipment) { const detail: Equipment = await request(`/equipment/${item.id}`); detail.attributes = parseAttributes(detail.attributes); selected.value = detail; detailUnitId.value = detail.unit_id; await loadFields(detail.category_id); events.value = await request(`/equipment/${item.id}/events`); await loadAttachments(detail.id); statusForm.value = { status: detail.status, description: '' }; view.value = 'detail' }
async function changeDetailUnit() { if (!selected.value) return; try { await request(`/equipment/${selected.value.id}/unit`, { method: 'PUT', body: JSON.stringify({ unitId: detailUnitId.value }) }); await openDetail(selected.value); await loadAll(); notify('所属单位已修改') } catch (e) { notify((e as Error).message, true) } }
async function updateStatus() { if (!selected.value) return; try { await request(`/equipment/${selected.value.id}/status`, { method: 'POST', body: JSON.stringify(statusForm.value) }); await openDetail(selected.value); await loadAll(); notify('装备状态已更新') } catch (e) { notify((e as Error).message, true) } }
function inputType(field: Field) { return field.field_type === 'INTEGER' || field.field_type === 'DECIMAL' ? 'number' : field.field_type === 'DATE' ? 'date' : field.field_type === 'DATETIME' ? 'datetime-local' : 'text' }
function stringAttribute(key: string) { const value = equipmentForm.value.attributes[key]; return typeof value === 'boolean' || value === undefined ? '' : String(value) }
function setStringAttribute(key: string, value: string) { equipmentForm.value.attributes[key] = value }
const availableEquipment = computed(() => equipment.value.filter(item => item.status === 'IN_STOCK'))
const canEditTask = computed(() => !!selectedTask.value && (isAdmin.value || selectedTask.value.task.created_by === user.value?.id))
function openTaskForm() { taskForm.value = { name: '', type: '', location: '', startTime: '', endTime: '', leader: user.value?.name || '', participants: '', description: '', equipmentIds: [] }; view.value = 'task-form' }
async function saveTask() { try { if (!taskForm.value.equipmentIds.length) throw new Error('请至少选择一件在库装备'); await request('/tasks', { method: 'POST', body: JSON.stringify(taskForm.value) }); await loadAll(); view.value = 'tasks'; notify('任务已创建，装备已锁定') } catch (e) { notify((e as Error).message, true) } }
async function openTaskDetail(task: Task) { selectedTask.value = await request(`/tasks/${task.id}`); view.value = 'task-detail' }
async function returnTaskEquipment(item: TaskEquipment) { if (!selectedTask.value) return; try { await request(`/tasks/${selectedTask.value.task.id}/equipment/${item.equipment_id}/return`, { method: 'POST', body: JSON.stringify({ ...returnForm.value, mileage: returnForm.value.mileage ? Number(returnForm.value.mileage) : null }) }); returnForm.value = { returnStatus: 'IN_STOCK', mileage: '', usageDescription: '', damageDescription: '', transferDescription: '', description: '' }; await openTaskDetail(selectedTask.value.task); await loadAll(); notify('装备已归还') } catch (e) { notify((e as Error).message, true) } }
async function completeTask() { if (!selectedTask.value) return; try { await request(`/tasks/${selectedTask.value.task.id}/complete`, { method: 'POST' }); await openTaskDetail(selectedTask.value.task); await loadAll(); notify('任务已完成') } catch (e) { notify((e as Error).message, true) } }
async function recordTaskEvent(item: TaskEquipment) { if (!selectedTask.value) return; try { await request(`/tasks/${selectedTask.value.task.id}/equipment/${item.equipment_id}/events`, { method: 'POST', body: JSON.stringify(eventForm.value) }); eventForm.value = { eventType: 'TRANSFER', handlerName: '', description: '' }; await openTaskDetail(selectedTask.value.task); await loadAll(); notify('事件已记录') } catch (e) { notify((e as Error).message, true) } }
function openTaskEvent(item: TaskEquipment, type: string) { eventEquipment.value = item; eventForm.value = { eventType: type, handlerName: '', description: '' }; (document.getElementById('task-event-dialog') as HTMLDialogElement | null)?.showModal() }
async function submitTaskEvent() { if (!eventEquipment.value) return; await recordTaskEvent(eventEquipment.value); (document.getElementById('task-event-dialog') as HTMLDialogElement | null)?.close() }
async function loadHistory() { try { const query = new URLSearchParams(); for (const [key, value] of Object.entries(historyFilter.value)) if (value) query.set(key, value); history.value = await request(`/equipment/history?${query}`); view.value = 'history' } catch (e) { notify((e as Error).message, true) } }
function eventName(type: string) { return ({ CREATED: '创建', STATUS_CHANGED: '状态变更', UNIT_CHANGED: '所属单位调整', TASK_ASSIGNED: '分配任务', TASK_RETURNED: '任务归还', TRANSFER: '转交', DAMAGE: '损坏', LOST: '丢失', ANOMALY: '异常' } as Record<string, string>)[type] || type }
function taskStatusName(status: string) { return ({ PLANNED: '计划中', EXECUTING: '执行中', COMPLETED: '已完成', CANCELLED: '已取消' } as Record<string, string>)[status] || status }
function eventDescription(event: HistoryEvent) { return event.event_type === 'UNIT_CHANGED' && (!event.description || event.description === '调整所属单位') ? '所属单位已调整' : event.description || '-' }
async function loadAttachments(equipmentId: number) { attachments.value = await request(`/attachments?equipmentId=${equipmentId}`) }
async function uploadAttachment(event: globalThis.Event) { if (!selected.value) return; const input = event.target as HTMLInputElement; const file = input.files?.[0]; if (!file) return; try { const form = new FormData(); form.append('file', file); form.append('equipmentId', String(selected.value.id)); const response = await fetch(`${api}/attachments`, { method: 'POST', headers: headers.value as Record<string, string>, body: form }); const data = await response.json().catch(() => ({})); if (!response.ok) throw new Error(data.message || '上传失败'); await loadAttachments(selected.value.id); notify('附件已上传') } catch (e) { notify((e as Error).message, true) } finally { input.value = '' } }
async function download(path: string) {
  try {
    const response = await fetch(`${api}${path}`, { headers: headers.value as Record<string, string> })
    if (!response.ok) {
      const data = await response.json().catch(() => ({}))
      throw new Error(data.message || '下载失败')
    }
    const disposition = response.headers.get('content-disposition') || ''
    const matched = disposition.match(/filename\*?=(?:UTF-8''|\")?([^;\"]+)/i)
    const filename = matched ? decodeURIComponent(matched[1].replace(/[\"]/g, '')) : 'download'
    const url = URL.createObjectURL(await response.blob())
    const link = document.createElement('a')
    link.href = url
    link.download = filename
    document.body.appendChild(link)
    link.click()
    link.remove()
    URL.revokeObjectURL(url)
  } catch (e) { notify((e as Error).message, true) }
}
function openReturnDialog(id: number) { (document.getElementById(`return-${id}`) as HTMLDialogElement | null)?.showModal() }
function closeReturnDialog(id: number) { (document.getElementById(`return-${id}`) as HTMLDialogElement | null)?.close() }
onMounted(() => loadAll().catch(e => notify((e as Error).message, true)))
</script>

<template>
  <main>
    <section v-if="!user" class="auth-card card"><h1>装备管理系统</h1><p class="muted">{{ authMode === 'login' ? '登录后管理装备' : '第一个注册用户自动成为管理者' }}</p><input v-if="authMode === 'register'" v-model="authForm.name" placeholder="姓名" /><input v-model="authForm.username" placeholder="用户名" /><input v-model="authForm.password" type="password" placeholder="密码（至少 6 位）" /><button @click="submitAuth">{{ authMode === 'login' ? '登录' : '注册并登录' }}</button><button class="text-button" @click="authMode = authMode === 'login' ? 'register' : 'login'">切换为{{ authMode === 'login' ? '注册' : '登录' }}</button></section>
    <template v-else>
      <header><div><h1>装备管理系统</h1><p class="muted">欢迎您！{{ user.name }}</p></div><nav><button class="secondary" @click="view = 'dashboard'; loadAll()">首页</button><button class="secondary" @click="view = 'list'; loadEquipment()">装备列表</button><button class="secondary" @click="view = 'tasks'; loadAll()">任务管理</button><button class="secondary" @click="loadHistory">使用历史</button><button v-if="isAdmin" class="secondary" @click="openFields(categories[0]?.id)">字段配置</button><button v-if="isAdmin" class="secondary" @click="openUsers">用户管理</button><button class="secondary" @click="openProfile">个人信息</button><button class="secondary" @click="logout">退出登录</button></nav></header>
      <p v-if="message" class="notice success">{{ message }}</p><p v-if="error" class="notice error">{{ error }}</p>
      <section v-if="view === 'dashboard'" class="card"><div class="section-title"><h2>运行概览</h2><div><button class="small secondary" @click="download('/export/equipment')">导出装备</button><button class="small secondary" @click="download('/export/tasks')">导出任务</button><button class="small secondary" @click="download('/export/history')">导出历史</button></div></div><div class="stat-grid"><div><strong>{{ dashboard?.equipment.total || 0 }}</strong><span>装备总数</span></div><div><strong>{{ dashboard?.equipment.in_stock || 0 }}</strong><span>在库</span></div><div><strong>{{ dashboard?.equipment.in_task || 0 }}</strong><span>执行任务中</span></div><div><strong>{{ dashboard?.equipment.maintenance || 0 }}</strong><span>维护保养中</span></div><div><strong>{{ dashboard?.equipment.disabled || 0 }}</strong><span>停用</span></div><div><strong>{{ dashboard?.tasks.executing || 0 }}</strong><span>执行中任务</span></div></div><h3>近期任务</h3><table><thead><tr><th>编号</th><th>名称</th><th>状态</th><th>负责人</th></tr></thead><tbody><tr v-for="task in dashboard?.recentTasks" :key="task.id"><td>{{ task.task_code }}</td><td>{{ task.name }}</td><td>{{ task.status }}</td><td>{{ task.leader || '-' }}</td></tr></tbody></table><h3>近期事件</h3><table><thead><tr><th>时间</th><th>装备</th><th>事件</th><th>说明</th></tr></thead><tbody><tr v-for="event in dashboard?.recentEvents" :key="event.id"><td>{{ new Date(event.occurred_at).toLocaleString() }}</td><td>{{ event.equipment_code }} · {{ event.equipment_name }}</td><td>{{ eventName(event.event_type) }}</td><td>{{ event.description || '-' }}</td></tr></tbody></table></section>
      <section v-if="view === 'profile'" class="card"><div class="section-title"><h2>个人信息</h2><button class="secondary" @click="view = 'dashboard'">返回首页</button></div><div class="form-grid"><label>用户名<input :value="profileForm.username" disabled /></label><label>用户类型<input :value="profileForm.role === 'ADMIN' ? '管理者' : '普通用户'" disabled /></label><label>姓名<em>*</em><input v-model="profileForm.name" /></label><label>工作单位<input v-model="profileForm.work_unit" placeholder="例如：某某单位" /></label><label>职务<input v-model="profileForm.job_title" placeholder="例如：设备管理员" /></label><label>联系方式<input v-model="profileForm.phone" placeholder="手机或办公电话" /></label><label>电子邮箱<input v-model="profileForm.email" type="email" /></label><label class="wide">联系地址<input v-model="profileForm.address" /></label><label class="wide">备注<textarea v-model="profileForm.remarks" placeholder="可补充填写其他基本信息" /></label></div><button @click="saveProfile">保存个人信息</button></section>
      <section v-if="view === 'users'" class="card"><div class="section-title"><h2>用户管理</h2><button class="secondary" @click="view = 'dashboard'">返回首页</button></div><p class="muted">仅管理者可以修改用户类型；不能修改自己的类型。</p><table><thead><tr><th>用户名</th><th>姓名</th><th>工作单位</th><th>职务</th><th>联系方式</th><th>用户类型</th><th>注册时间</th></tr></thead><tbody><tr v-for="item in managedUsers" :key="item.id"><td>{{ item.username }}</td><td>{{ item.name }}</td><td>{{ item.work_unit || '-' }}</td><td>{{ item.job_title || '-' }}</td><td>{{ item.phone || item.email || '-' }}</td><td><select :value="item.role" :disabled="item.id === user.id" @change="updateUserRole(item, ($event.target as HTMLSelectElement).value as 'ADMIN' | 'USER')"><option value="USER">普通用户</option><option value="ADMIN">管理者</option></select></td><td>{{ new Date(item.created_at).toLocaleString() }}</td></tr></tbody></table><p v-if="!managedUsers.length" class="muted">暂无用户</p></section>
      <section v-if="view === 'list'" class="unit-workspace"><aside class="unit-sidebar"><div class="unit-sidebar-head"><div><span class="eyebrow">ORGANIZATION</span><h2>单位导航</h2></div><button class="small secondary" @click="selectUnit(null)">全部</button></div><button class="unit-node root" :class="{ active: selectedUnitId === null }" @click="selectUnit(null)"><span>◈</span>全部单位</button><div class="unit-tree"><template v-for="level1 in unitChildren(null)" :key="level1.id"><div class="unit-node-wrap"><button class="unit-node level-1" :class="{ active: selectedUnitId === level1.id }" @click="selectUnit(level1.id)"><span>▾</span>{{ level1.name }}</button><button v-if="isAdmin" class="unit-edit" title="修改单位名称" @click.stop="startRenameUnit(level1)">✎</button></div><template v-for="level2 in unitChildren(level1.id)" :key="level2.id"><div class="unit-node-wrap"><button class="unit-node level-2" :class="{ active: selectedUnitId === level2.id }" @click="selectUnit(level2.id)"><span>↳</span>{{ level2.name }}</button><button v-if="isAdmin" class="unit-edit" title="修改单位名称" @click.stop="startRenameUnit(level2)">✎</button></div><div v-for="level3 in unitChildren(level2.id)" :key="level3.id" class="unit-node-wrap"><button class="unit-node level-3" :class="{ active: selectedUnitId === level3.id }" @click="selectUnit(level3.id)"><span>•</span>{{ level3.name }}</button><button v-if="isAdmin" class="unit-edit" title="修改单位名称" @click.stop="startRenameUnit(level3)">✎</button></div></template></template></div><div v-if="isAdmin" class="unit-create"><h3>新增单位</h3><input v-model="unitForm.name" placeholder="单位名称" /><select v-model="unitForm.parentId"><option value="">一级单位</option><option v-for="unit in units.filter(item => item.level < 3)" :key="unit.id" :value="String(unit.id)">{{ '　'.repeat(unit.level - 1) }}{{ unit.name }}</option></select><button class="small" @click="createUnit">添加单位</button></div></aside><div class="equipment-board"><div class="section-title"><div><span class="eyebrow">EQUIPMENT OVERVIEW</span><h2>{{ selectedUnitId ? units.find(unit => unit.id === selectedUnitId)?.name : '全部装备' }}</h2><p class="muted">共 {{ equipment.length }} 台装备 · 点击卡片查看完整信息</p></div><button @click="blankEquipment">新增装备</button></div><div class="list-filters"><input v-model="listFilter.keyword" placeholder="搜索编号或名称" @keyup.enter="loadEquipment" /><select v-model="listFilter.categoryId"><option value="">全部类别</option><option v-for="category in categories" :key="category.id" :value="String(category.id)">{{ category.name }}</option></select><select v-model="listFilter.status"><option value="">全部状态</option><option v-for="(label, key) in statusNames" :key="key" :value="key">{{ label }}</option></select><button @click="loadEquipment">筛选</button></div><div class="equipment-cards"><article v-for="item in equipment" :key="item.id" class="equipment-card" tabindex="0" @click="openDetail(item)" @keydown.enter="openDetail(item)"><div class="equipment-image"><img v-if="equipmentImage(item)" :src="equipmentImage(item)" :alt="item.name" /><span v-else class="image-placeholder">◈<small>暂无装备图片</small></span><span class="status-tag" :class="`status-${item.status.toLowerCase()}`">{{ statusNames[item.status] || item.status }}</span></div><div class="equipment-card-body"><div class="card-code">{{ item.equipment_code }}</div><h3>{{ item.name }}</h3><p class="category-tag">{{ item.category_name }} · {{ item.unit_name }}</p><p v-if="briefAttributes(item)" class="card-attributes">{{ briefAttributes(item) }}</p><p v-else class="card-attributes">地点：{{ item.location || '未填写' }}</p><p v-if="item.task_name" class="task-line">◉ 参与任务：{{ item.task_name }}</p><p v-else class="task-line muted">○ 当前未参与任务</p></div></article></div><p v-if="!equipment.length" class="empty-state">该单位下暂无装备</p></div><dialog id="unit-rename-dialog"><form method="dialog" class="dialog-form"><h3>修改单位名称</h3><input v-model="unitRenameName" placeholder="单位名称" /><div><button type="button" @click="renameUnit(); (document.getElementById('unit-rename-dialog') as HTMLDialogElement)?.close()">保存</button><button class="secondary" value="cancel">取消</button></div></form></dialog></section>
      <section v-if="view === 'tasks'" class="card"><div class="section-title"><h2>任务管理</h2><button @click="openTaskForm">创建任务</button></div><table><thead><tr><th>任务编号</th><th>名称</th><th>状态</th><th>负责人</th><th>装备</th><th>创建人</th><th>操作</th></tr></thead><tbody><tr v-for="task in tasks" :key="task.id"><td>{{ task.task_code }}</td><td>{{ task.name }}</td><td><span class="badge">{{ task.status === 'EXECUTING' ? '执行中' : task.status === 'COMPLETED' ? '已完成' : task.status }}</span></td><td>{{ task.leader || '-' }}</td><td>{{ task.equipment_total - task.equipment_outstanding }}/{{ task.equipment_total }} 已归还</td><td>{{ task.creator_name }}</td><td><button class="small secondary" @click="openTaskDetail(task)">详情</button></td></tr></tbody></table><p v-if="!tasks.length" class="muted">暂无任务</p></section>
      <section v-if="view === 'history'" class="card"><div class="section-title"><h2>装备使用与异常历史</h2><button class="secondary" @click="view = 'list'">返回装备列表</button></div><div class="history-filters"><select v-model="historyFilter.equipmentId"><option value="">全部装备</option><option v-for="item in equipment" :key="item.id" :value="String(item.id)">{{ item.equipment_code }} · {{ item.name }}</option></select><select v-model="historyFilter.taskId"><option value="">全部任务</option><option v-for="task in tasks" :key="task.id" :value="String(task.id)">{{ task.task_code }} · {{ task.name }}</option></select><select v-model="historyFilter.eventType"><option value="">全部事件</option><option value="TRANSFER">转交</option><option value="DAMAGE">损坏</option><option value="LOST">丢失</option><option value="ANOMALY">异常</option><option value="TASK_ASSIGNED">分配任务</option><option value="TASK_RETURNED">任务归还</option><option value="STATUS_CHANGED">状态变更</option></select><input v-model="historyFilter.from" type="datetime-local" /><input v-model="historyFilter.to" type="datetime-local" /><button @click="loadHistory">查询</button></div><table><thead><tr><th>时间</th><th>装备</th><th>关联任务</th><th>事件</th><th>状态变化</th><th>操作人</th><th>说明</th></tr></thead><tbody><tr v-for="item in history" :key="item.id"><td>{{ new Date(item.occurred_at).toLocaleString() }}</td><td>{{ item.equipment_code }} · {{ item.equipment_name }}</td><td>{{ item.task_code || '-' }}</td><td>{{ eventName(item.event_type) }}</td><td>{{ statusNames[item.old_status || ''] || '-' }} → {{ statusNames[item.new_status || ''] || '-' }}</td><td>{{ item.operator_name || '-' }}</td><td>{{ item.description || '-' }}</td></tr></tbody></table><p v-if="!history.length" class="muted">没有符合条件的历史记录</p></section>
      <section v-if="view === 'task-form'" class="card"><div class="section-title"><h2>创建任务</h2><button class="secondary" @click="view = 'tasks'">取消</button></div><div class="form-grid"><label>任务名称<em>*</em><input v-model="taskForm.name" /></label><label>任务类型<input v-model="taskForm.type" /></label><label>任务地点<input v-model="taskForm.location" /></label><label>开始时间<input v-model="taskForm.startTime" type="datetime-local" /></label><label>结束时间<input v-model="taskForm.endTime" type="datetime-local" /></label><label>负责人<input v-model="taskForm.leader" /></label><label class="wide">参与人员<input v-model="taskForm.participants" placeholder="可自行填写" /></label><label class="wide">任务说明<textarea v-model="taskForm.description" /></label></div><h3>选择在库装备</h3><p class="muted">创建后所选装备将立即进入“执行任务中”状态，无法再分配给其他任务。</p><div class="equipment-picker"><label v-for="item in availableEquipment" :key="item.id"><input v-model="taskForm.equipmentIds" type="checkbox" :value="item.id" />{{ item.equipment_code }} · {{ item.name }}（{{ item.category_name }}）</label><p v-if="!availableEquipment.length" class="muted">当前没有可用的在库装备。</p></div><button @click="saveTask">创建并锁定装备</button></section>
      <section v-if="view === 'task-detail' && selectedTask" class="card"><div class="section-title"><h2>任务详情：{{ selectedTask.task.task_code }}</h2><button class="secondary" @click="view = 'tasks'">返回任务列表</button></div><dl class="detail-grid"><dt>任务名称</dt><dd>{{ selectedTask.task.name }}</dd><dt>状态</dt><dd>{{ selectedTask.task.status === 'EXECUTING' ? '执行中' : selectedTask.task.status === 'COMPLETED' ? '已完成' : selectedTask.task.status }}</dd><dt>负责人</dt><dd>{{ selectedTask.task.leader || '-' }}</dd><dt>地点</dt><dd>{{ selectedTask.task.location || '-' }}</dd><dt>说明</dt><dd>{{ selectedTask.task.description || '-' }}</dd></dl><h3>任务装备</h3><table><thead><tr><th>装备编号</th><th>装备名称</th><th>类别</th><th>当前使用人</th><th>归还情况</th><th>操作</th></tr></thead><tbody><tr v-for="item in selectedTask.equipment" :key="item.id"><td>{{ item.equipment_code }}</td><td>{{ item.equipment_name }}</td><td>{{ item.category_name }}</td><td>{{ item.assigned_user || '-' }}</td><td>{{ item.returned_at ? `已归还（${statusNames[item.return_status || ''] || item.return_status}）` : '使用中' }}</td><td v-if="canEditTask && !item.returned_at && selectedTask.task.status === 'EXECUTING'"><button class="small" @click="returnForm = { returnStatus: 'IN_STOCK', mileage: '', usageDescription: '', damageDescription: '', transferDescription: '', description: '' }; openReturnDialog(item.id)">归还</button><button class="small secondary" @click="openTaskEvent(item, 'TRANSFER')">转交</button><button class="small warning" @click="openTaskEvent(item, 'ANOMALY')">异常</button><button class="small danger" @click="openTaskEvent(item, 'DAMAGE')">损坏</button><button class="small danger" @click="openTaskEvent(item, 'LOST')">丢失</button></td><td v-else>-</td><dialog :id="`return-${item.id}`"><form method="dialog" class="dialog-form"><h3>归还 {{ item.equipment_name }}</h3><label>归还后状态<select v-model="returnForm.returnStatus"><option value="IN_STOCK">在库</option><option value="MAINTENANCE">维护保养中</option></select></label><label>里程/读数<input v-model="returnForm.mileage" type="number" step="any" /></label><label>使用说明<textarea v-model="returnForm.usageDescription" /></label><label>损坏/异常说明<textarea v-model="returnForm.damageDescription" /></label><label>归还说明<textarea v-model="returnForm.description" /></label><div><button type="button" @click="returnTaskEquipment(item); closeReturnDialog(item.id)">确认归还</button><button class="secondary" value="cancel">取消</button></div></form></dialog></tr></tbody></table><button v-if="canEditTask && selectedTask.task.status === 'EXECUTING'" class="complete-button" @click="completeTask">完成任务（需全部装备已归还）</button><dialog id="task-event-dialog"><form method="dialog" class="dialog-form"><h3>{{ eventEquipment?.equipment_name }} · {{ eventName(eventForm.eventType) }}</h3><label v-if="eventForm.eventType === 'TRANSFER'">接收人员<input v-model="eventForm.handlerName" placeholder="转交给谁" /></label><label>事件说明<textarea v-model="eventForm.description" placeholder="请记录具体经过、处理情况等" /></label><p v-if="eventForm.eventType === 'DAMAGE'" class="muted">记录损坏后，该装备将结束本任务使用并进入维护保养中。</p><p v-if="eventForm.eventType === 'LOST'" class="muted">记录丢失后，该装备将结束本任务使用并被标记为停用。</p><div><button type="button" @click="submitTaskEvent">确认记录</button><button class="secondary" value="cancel">取消</button></div></form></dialog></section>
      <section v-if="view === 'fields'" class="card"><div class="section-title"><h2>类别与动态字段</h2><button class="secondary" @click="view = 'list'">返回列表</button></div><div class="row admin-row"><input v-model="categoryForm.name" placeholder="新类别名称" /><input v-model="categoryForm.description" placeholder="类别说明" /><button @click="createCategory">创建类别</button></div><div class="tabs"><button v-for="category in categories" :key="category.id" :class="{ active: category.id === selectedCategoryId }" @click="openFields(category.id)">{{ category.name }}</button></div><h3>为“{{ categories.find(c => c.id === selectedCategoryId)?.name }}”添加字段</h3><div class="field-grid"><input v-model="fieldForm.fieldName" @blur="normalizeFieldKey" placeholder="字段名称，如车牌号" /><input v-model="fieldForm.fieldKey" placeholder="字段键名，如 plate_number" /><select v-model="fieldForm.fieldType"><option v-for="(label, type) in fieldTypeNames" :key="type" :value="type">{{ label }}</option></select><label><input v-model="fieldForm.required" type="checkbox" /> 必填</label><input v-if="fieldForm.fieldType === 'SELECT'" v-model="fieldForm.optionsText" placeholder="选项，以逗号分隔" /><button @click="addField">添加字段</button></div><table><thead><tr><th>字段名称</th><th>键名</th><th>类型</th><th>必填</th><th>选项</th><th>操作</th></tr></thead><tbody><tr v-for="field in fields" :key="field.id"><td>{{ field.field_name }}</td><td>{{ field.field_key }}</td><td>{{ fieldTypeNames[field.field_type] }}</td><td>{{ field.required ? '是' : '否' }}</td><td>{{ parseOptions(field).join('、') || '-' }}</td><td><button class="small danger" @click="removeField(field)">删除</button></td></tr></tbody></table></section>
      <section v-if="view === 'form'" class="card"><div class="section-title"><h2>{{ equipmentForm.id ? '编辑装备' : '新增装备' }}</h2><button class="secondary" @click="view = 'list'">取消</button></div><div class="form-grid"><label>所属单位<em>*</em><select v-model.number="equipmentForm.unitId"><option v-for="unit in units" :key="unit.id" :value="unit.id">{{ '　'.repeat(unit.level - 1) }}{{ unit.name }}</option></select></label><label>装备类别<select v-model.number="equipmentForm.categoryId"><option v-for="category in categories" :key="category.id" :value="category.id">{{ category.name }}</option></select></label><label>装备名称<input v-model="equipmentForm.name" required /></label><label>存放地点<input v-model="equipmentForm.location" /></label><label>所属部门<input v-model="equipmentForm.department" /></label><template v-for="field in fields" :key="field.id"><label v-if="field.field_type === 'BOOLEAN'" class="checkbox"><input :checked="equipmentForm.attributes[field.field_key] === true" type="checkbox" @change="equipmentForm.attributes[field.field_key] = ($event.target as HTMLInputElement).checked" />{{ field.field_name }}<em v-if="field.required">*</em></label><label v-else-if="field.field_type === 'TEXTAREA'" class="wide">{{ field.field_name }}<em v-if="field.required">*</em><textarea :value="stringAttribute(field.field_key)" @input="setStringAttribute(field.field_key, ($event.target as HTMLTextAreaElement).value)" /></label><label v-else-if="field.field_type === 'SELECT'">{{ field.field_name }}<em v-if="field.required">*</em><select :value="stringAttribute(field.field_key)" @change="setStringAttribute(field.field_key, ($event.target as HTMLSelectElement).value)"><option value="">请选择</option><option v-for="option in parseOptions(field)" :key="option" :value="option">{{ option }}</option></select></label><label v-else>{{ field.field_name }}<em v-if="field.required">*</em><input :value="stringAttribute(field.field_key)" :type="inputType(field)" :step="field.field_type === 'DECIMAL' ? 'any' : undefined" @input="setStringAttribute(field.field_key, ($event.target as HTMLInputElement).value)" /></label></template></div><button @click="saveEquipment">保存装备</button></section>
      <section v-if="view === 'detail' && selected" class="card"><div class="section-title"><h2>装备详情：{{ selected.equipment_code }}</h2><div><button v-if="canEdit" @click="editEquipment(selected)">编辑</button><button class="secondary" @click="view = 'list'">返回列表</button></div></div><dl class="detail-grid"><dt>名称</dt><dd>{{ selected.name }}</dd><dt>类别</dt><dd>{{ selected.category_name }}</dd><dt>所属单位</dt><dd>{{ selected.unit_name || '-' }}</dd><dt>状态</dt><dd>{{ statusNames[selected.status] }}</dd><dt>地点</dt><dd>{{ selected.location || '-' }}</dd><dt>部门</dt><dd>{{ selected.department || '-' }}</dd><template v-for="field in fields" :key="field.id"><dt>{{ field.field_name }}</dt><dd>{{ selected.attributes?.[field.field_key] === true ? '是' : selected.attributes?.[field.field_key] === false ? '否' : selected.attributes?.[field.field_key] || '-' }}</dd></template></dl><div v-if="canEdit" class="status-box"><h3>调整所属单位</h3><select v-model.number="detailUnitId"><option v-for="unit in units" :key="unit.id" :value="unit.id">{{ '　'.repeat(unit.level - 1) }}{{ unit.name }}</option></select><button @click="changeDetailUnit">保存所属单位</button></div><div v-if="canEdit" class="status-box"><h3>变更状态 / 停用装备</h3><select v-model="statusForm.status"><option v-for="(label, key) in statusNames" :key="key" :value="key">{{ label }}</option></select><input v-model="statusForm.description" placeholder="状态变更说明" /><button @click="updateStatus">确认变更</button></div><h3>附件</h3><div class="attachment-box"><label v-if="canEdit" class="upload-label">上传附件<input type="file" @change="uploadAttachment" /></label><p v-if="!attachments.length" class="muted">暂无附件</p><ul><li v-for="file in attachments" :key="file.id"><button class="text-button" @click="download(`/attachments/${file.id}/download`)">{{ file.file_name }}</button><span>{{ file.file_size ? `${Math.ceil(file.file_size / 1024)} KB` : '' }}</span></li></ul></div><h3>状态与操作历史</h3><table><thead><tr><th>时间</th><th>事件</th><th>状态变化</th><th>操作人</th><th>说明</th></tr></thead><tbody><tr v-for="event in events" :key="event.id"><td>{{ new Date(event.occurred_at).toLocaleString() }}</td><td>{{ eventName(event.event_type) }}</td><td>{{ statusNames[event.old_status || ''] || '-' }} → {{ statusNames[event.new_status || ''] || '-' }}</td><td>{{ event.operator_name || '-' }}</td><td>{{ event.description || '-' }}</td></tr></tbody></table></section>
    </template>
  </main>
</template>
